globalThis.RULEBOOK = {"sources":{"amlr":{"title":"Regulation (EU) 2024/1624","short":"EU Anti-Money Laundering Regulation","url":"https://eur-lex.europa.eu/eli/reg/2024/1624/oj","edition":"Official Journal of the European Union, L series, 19 June 2024"},"tfr":{"title":"Regulation (EU) 2023/1113","short":"EU Transfer of Funds Regulation","url":"https://eur-lex.europa.eu/eli/reg/2023/1113/oj","edition":"Official Journal of the European Union, L 150, 9 June 2023"},"fatf":{"title":"The FATF Recommendations","short":"FATF Recommendations","url":"https://www.fatf-gafi.org/en/publications/Fatfrecommendations/Fatf-recommendations.html","edition":"International Standards on Combating Money Laundering and the Financing of Terrorism and Proliferation, updated June 2026"}},"passages":[{"id":"amlr-19-1","source":"amlr","cite":"Article 19(1)","topic":"When customer due diligence is required","quote":"Obliged entities shall apply customer due diligence measures in any of the following circumstances: (a) when establishing a business relationship; (b) when carrying out an occasional transaction of a value of at least EUR 10 000, or the equivalent in national currency, whether that transaction is carried out in a single operation or through linked transactions, or a lower value laid down pursuant to paragraph 9; (c) when participating in the creation of a legal entity, the setting up of a legal arrangement or, for the obliged entities referred to in Article 3, points (3) (a), (b) or (c), in the transfer of ownership of a legal entity, irrespective of the value of the transaction; (d) when there is a suspicion of money laundering or terrorist financing, regardless of any derogation, exemption or threshold; (e) when there are doubts about the veracity or adequacy of previously obtained customer identification data; (f) when there are doubts as to whether the person they interact with is the customer or person authorised to act on behalf of the customer.","excerpt":false,"plain":"This is the list of moments when a firm must run its identity and risk checks, including whenever it suspects money laundering.","asks":["when do we have to do customer due diligence","when is KYC required","what triggers identity checks","occasional transaction threshold 10000"],"keywords":["kyc","know your customer","onboarding","identify","verify","trigger","threshold"]},{"id":"amlr-19-3","source":"amlr","cite":"Article 19(3)","topic":"Crypto firms: the 1,000 euro threshold","quote":"By way of derogation from paragraph 1, point (b), crypto-asset service providers shall: (a) apply customer due diligence measures when carrying out an occasional transaction that amounts to a value of at least EUR 1 000, or the equivalent in national currency, whether the transaction is carried out in a single operation or through linked transactions; (b) apply at least customer due diligence measures referred to in Article 20(1), point (a), when carrying out an occasional transaction where the value is below EUR 1 000, or the equivalent in national currency, whether the transaction is carried out in a single operation or through linked transactions.","excerpt":false,"plain":"For crypto-asset service providers the threshold for one-off transactions is 1,000 euro, not 10,000. Below that they still apply the basic identification step.","asks":["what is the threshold for crypto transactions","crypto customer due diligence threshold","do crypto firms need kyc for small transactions","1000 euro crypto"],"keywords":["crypto","crypto-asset","cryptocurrency","bitcoin","exchange","occasional","one-off","linked transactions","1000","threshold"]},{"id":"amlr-20-1","source":"amlr","cite":"Article 20(1)","topic":"What customer due diligence consists of","quote":"For the purpose of conducting customer due diligence, obliged entities shall apply all of the following measures: (a) identifying the customer and verifying the customer’s identity; (b) identifying the beneficial owners and taking reasonable measures to verify their identity so that the obliged entity is satisfied that it knows who the beneficial owner is and that it understands the ownership and control structure of the customer; (c) assessing and, as appropriate, obtaining information on and understanding the purpose and intended nature of the business relationship or the occasional transactions; (d) verifying whether the customer or the beneficial owners are subject to targeted financial sanctions, and, in the case of a customer or party to a legal arrangement who is a legal entity, whether natural or legal persons subject to targeted financial sanctions control the legal entity or have more than 50 % of the proprietary rights of that legal entity or majority interest in it, whether individually or collectively; (e) assessing and, as appropriate, obtaining information on the nature of the customers’ business, including, in the case of undertakings, whether they carry out activities, or of their employment or occupation; (f) conducting ongoing monitoring of the business relationship including scrutiny of transactions undertaken throughout the course of the business relationship to ensure that the transactions being conducted are consistent with the obliged entity’s knowledge of the customer, the business and risk profile, including where necessary the source of funds; (g) determining whether the customer, the beneficial owner of the customer and, where relevant, the person on whose behalf or for the benefit of whom a transaction or activity is being carried out is a politically exposed person, a family member or person known to be a close associate; (h) where a transaction or activity is being conducted on behalf of or for the benefit of natural persons other than the customer, identifying and verifying the identity of those natural persons; (i) verifying that any person purporting to act on behalf of the customer is so authorised and identify and verify their identity.","excerpt":false,"plain":"The full list of checks: identify the customer, find the beneficial owner, understand the purpose of the relationship, screen for sanctions, check for politically exposed persons, and monitor.","asks":["what does customer due diligence include","what are the KYC steps","what checks must be done on a customer","do we need to screen for sanctions"],"keywords":["kyc","identify","verify","beneficial owner","sanctions","pep","politically exposed","purpose","screening","measures","checks"]},{"id":"amlr-20-2","source":"amlr","cite":"Article 20(2)","topic":"Checks must match the risk of each customer","quote":"Obliged entities shall determine the extent of the measures referred to in paragraph 1 on the basis of an individual analysis of the risks of money laundering and terrorist financing having regard to the specific characteristics of the client and of the business relationship or occasional transaction, and taking into account the business-wide risk assessment by the obliged entity pursuant to Article 10 and the money laundering and terrorist financing variables set out in Annex I as well as the risk factors set out in Annexes II and III. Where obliged entities identify an increased risk of money laundering or terrorist financing they shall apply enhanced due diligence measures pursuant to Section 4 of this Chapter. Where situations of lower risk are identified, obliged entities may apply simplified due diligence measures pursuant to Section 3 of this Chapter.","excerpt":false,"plain":"How deep the checks go depends on the risk of the individual customer. Higher risk means enhanced checks. Lower risk allows simplified checks.","asks":["is customer due diligence risk based","what is a risk-based approach to customer checks","when to use enhanced due diligence","how do we decide how much due diligence"],"keywords":["risk-based","risk based","proportionate","enhanced","simplified","individual","risk assessment","extent"]},{"id":"amlr-21-1","source":"amlr","cite":"Article 21(1), first subparagraph","topic":"If the checks cannot be completed","quote":"Where an obliged entity is unable to comply with the requirement to apply customer due diligence measures laid down in Article 20(1), it shall refrain from carrying out a transaction or establishing a business relationship, and shall terminate the business relationship and consider reporting a suspicious transaction to the FIU in relation to the customer in accordance with Article 69.","excerpt":false,"plain":"If a firm cannot finish its customer checks, it must not transact or onboard, must end an existing relationship, and must consider reporting its suspicion.","asks":["what if the customer does not provide documents","what to do if we cannot complete kyc","can we onboard a customer without full due diligence","failed identity verification"],"keywords":["unable","cannot","refuse","terminate","offboard","exit","reject","incomplete","documents","failed"]},{"id":"amlr-26-1","source":"amlr","cite":"Article 26(1), first subparagraph","topic":"Ongoing monitoring of customers and transactions","quote":"Obliged entities shall conduct ongoing monitoring of business relationships, including transactions undertaken by the customer throughout the course of a business relationship, to ensure that those transactions are consistent with the obliged entity’s knowledge of the customer, the customer’s business activity and risk profile, and where necessary, with the information about the origin and destination of the funds and to detect those transactions that shall be made subject to a more thorough assessment pursuant to Article 69(2).","excerpt":false,"plain":"After onboarding, firms must keep watching transactions and check that they fit what they know about the customer. Transactions that do not fit get a closer look.","asks":["do we have to monitor transactions","what is ongoing monitoring","transaction monitoring requirement","must we keep monitoring customers after onboarding"],"keywords":["transaction monitoring","monitor","monitoring","ongoing","business relationship","consistent","risk profile","alerts","unusual"]},{"id":"amlr-26-2","source":"amlr","cite":"Article 26(2)","topic":"How often customer information must be refreshed","quote":"In the context of the ongoing monitoring referred to in paragraph 1, obliged entities shall ensure that the relevant documents, data or information of the customer are kept up to date. The period between updates of customer information pursuant to the first subparagraph shall be dependent on the risk posed by the business relationship and shall not in any case exceed: (a) for higher risk customers to which measures under Section 4 of this Chapter apply, 1 year; (b) for all other customers, 5 years.","excerpt":false,"plain":"Customer information must be updated at least every year for higher risk customers and at least every five years for everyone else.","asks":["how often must kyc be refreshed","how often do we update customer information","periodic review frequency","kyc refresh for high risk customers"],"keywords":["refresh","update","periodic","review","frequency","perpetual kyc","annual","every year","five years","high risk","higher risk"]},{"id":"amlr-33-1","source":"amlr","cite":"Article 33(1)","topic":"Simplified due diligence for low risk","quote":"Where, taking into account the risk factors set out in Annexes II and III, the business relationship or transaction present a low degree of risk, obliged entities may apply the following simplified due diligence measures: (a) verifying the identity of the customer and the beneficial owner after the establishment of the business relationship, provided that the specific lower risk identified justified such postponement, but in any case no later than 60 days of the relationship being established; (b) reducing the frequency of customer identification updates; (c) reducing the amount of information collected to identify the purpose and intended nature of the business relationship or occasional transaction or inferring it from the type of transactions or business relationship established; (d) reducing the frequency or degree of scrutiny of transactions carried out by the customer; (e) applying any other relevant simplified due diligence measure identified by AMLA pursuant to Article 28.","excerpt":false,"plain":"Where risk is low, firms may use lighter measures, such as verifying identity a little later (within 60 days), updating information less often, or scrutinising transactions less closely.","asks":["when can we use simplified due diligence","what is simplified kyc","can we reduce checks for low risk customers","delay identity verification"],"keywords":["simplified","lower risk","low risk","reduced","lighter","60 days","postpone"]},{"id":"amlr-33-1b","source":"amlr","cite":"Article 33(1), last sentence","topic":"Simplified checks never mean no monitoring","quote":"However, obliged entities shall carry out sufficient monitoring of the transactions and business relationship to enable the detection of unusual or suspicious transactions.","excerpt":false,"plain":"Even for low risk customers, a firm must still monitor enough to spot unusual or suspicious transactions.","asks":["can we skip monitoring for low risk customers","is monitoring needed under simplified due diligence","do low risk customers need transaction monitoring"],"keywords":["simplified","low risk","monitoring","unusual","suspicious","still"]},{"id":"amlr-34-2","source":"amlr","cite":"Article 34(2)","topic":"Which transactions must be examined more closely","quote":"Obliged entities shall examine the origin and destination of funds involved in, and the purpose of, all transactions that fulfil at least one of the following conditions: (a) the transaction is of a complex nature; (b) the transaction is unusually large; (c) the transaction is conducted in an unusual pattern; (d) the transaction does not have an apparent economic or lawful purpose.","excerpt":false,"plain":"Transactions that are complex, unusually large, follow an unusual pattern, or have no apparent economic or lawful purpose must be examined, including where the money came from and where it goes.","asks":["what makes a transaction unusual","which transactions need extra scrutiny","what should transaction monitoring look for","unusually large transactions","unusual pattern"],"keywords":["unusual","complex","large","pattern","purpose","economic","lawful","origin of funds","destination","scrutiny","red flags","monitoring","alerts"]},{"id":"amlr-34-4","source":"amlr","cite":"Article 34(4)","topic":"Enhanced due diligence measures","quote":"With the exception of the cases covered by Section 2 of this Chapter, in cases of higher risk as referred to in paragraph 1 of this Article, obliged entities shall apply enhanced due diligence measures, proportionate to the higher risks identified, which may include the following measures: (a) obtaining additional information on the customer and the beneficial owners; (b) obtaining additional information on the intended nature of the business relationship; (c) obtaining additional information on the source of funds, and source of wealth of the customer and of the beneficial owners; (d) obtaining information on the reasons for the intended or performed transactions and their consistency with the business relationship; (e) obtaining the approval of senior management for establishing or continuing the business relationship; (f) conducting enhanced monitoring of the business relationship by increasing the number and timing of controls applied, and selecting patterns of transactions that need further examination; (g) requiring the first payment to be carried out through an account in the customer’s name with a credit institution subject to customer due diligence standards that are not less robust than those laid down in this Regulation.","excerpt":false,"plain":"The menu of extra measures for higher risk cases: more information, source of funds and wealth, senior management approval, and closer monitoring.","asks":["what is enhanced due diligence","what extra checks for high risk customers","do we need senior management approval","source of funds and source of wealth","edd measures"],"keywords":["enhanced","edd","higher risk","high risk","source of funds","source of wealth","senior management","approval","additional information","enhanced monitoring"]},{"id":"amlr-40-1","source":"amlr","cite":"Article 40(1)","topic":"Transfers to and from self-hosted wallets","quote":"Crypto-asset service providers shall identify and assess the risk of money laundering and financing of terrorism associated with transfers of crypto-assets directed to or originating from a self-hosted address. To that end, crypto-asset service providers shall have in place internal policies, procedures and controls. Crypto-asset service providers shall apply mitigating measures commensurate with the risks identified. Those mitigating measures shall include one or more of the following: (a) taking risk-based measures to identify, and verify the identity of, the originator or beneficiary of a transfer made from or to a self-hosted address or beneficial owner of such originator or beneficiary, including through reliance on third parties; (b) requiring additional information on the origin and destination of the crypto-assets; (c) conducting enhanced ongoing monitoring of transactions with a self-hosted address; (d) any other measure to mitigate and manage the risks of money laundering and financing of terrorism as well as the risk of non-implementation and evasion of targeted financial sanctions.","excerpt":false,"plain":"Crypto firms must assess the risk of transfers to or from wallets that are not held at a regulated provider, and apply measures that fit the risk, such as asking for more information or monitoring more closely.","asks":["what about unhosted wallets","how to handle self-hosted wallet transfers","private wallet risk","do we need to verify wallet ownership","unhosted wallet rules"],"keywords":["self-hosted","unhosted","private wallet","wallet","crypto","crypto-asset","address","ownership","enhanced monitoring"]},{"id":"amlr-42-1","source":"amlr","cite":"Article 42(1)","topic":"Extra measures for politically exposed persons","quote":"In addition to the customer due diligence measures laid down in Article 20, obliged entities shall apply the following measures with respect to occasional transactions or business relationships with politically exposed persons: (a) obtain senior management approval for carrying out occasional transactions or for establishing or continuing business relationships with politically exposed persons; (b) take adequate measures to establish the source of wealth and source of funds that are involved in business relationships or occasional transactions with politically exposed persons; (c) conduct enhanced, ongoing monitoring of those business relationships.","excerpt":false,"plain":"For politically exposed persons a firm needs senior management approval, must establish source of wealth and source of funds, and must monitor more closely.","asks":["what do we do with a PEP customer","pep requirements","do we need approval to onboard a politically exposed person","source of wealth for pep"],"keywords":["pep","peps","politically exposed","senior management","approval","source of wealth","source of funds","enhanced monitoring"]},{"id":"amlr-45-2","source":"amlr","cite":"Article 45(2)","topic":"How long someone stays treated as a politically exposed person","quote":"Obliged entities shall apply one or more of the measures referred to in Article 34(4) to mitigate the risks posed by the politically exposed person until such time as the risks referred to in paragraph 1 of this Article no longer exist, but in any case for not less than 12 months following the time when the individual ceased to be entrusted with a prominent public function.","excerpt":false,"plain":"After someone leaves a prominent public function, firms must keep applying risk measures for at least 12 months, and longer if the risk remains.","asks":["how long is someone a PEP after leaving office","former pep","when does pep status end","12 months after leaving public function"],"keywords":["former","ceased","no longer","left office","12 months","twelve months","pep","politically exposed"]},{"id":"amlr-2-34","source":"amlr","cite":"Article 2(1), point (34), opening","topic":"Who counts as a politically exposed person","quote":"‘politically exposed person’ means a natural person who is or has been entrusted with prominent public functions including: (a) in a Member State: (i) heads of State, heads of government, ministers and deputy or assistant ministers;","excerpt":true,"plain":"A politically exposed person is someone who holds or has held a prominent public function. The source lists many roles. This excerpt shows only the first.","asks":["what is a PEP","who is a politically exposed person","definition of politically exposed person"],"keywords":["pep","politically exposed","definition","prominent public function","minister","head of state"]},{"id":"amlr-2-28","source":"amlr","cite":"Article 2(1), point (28)","topic":"What a beneficial owner is","quote":"‘beneficial owner’ means any natural person who ultimately owns or controls a legal entity or an express trust or similar legal arrangement;","excerpt":false,"plain":"A beneficial owner is the real person who ultimately owns or controls a company, trust or similar structure.","asks":["what is a beneficial owner","ubo definition","ultimate beneficial owner"],"keywords":["beneficial owner","ubo","ultimate","owns","controls","definition","company","trust"]},{"id":"amlr-10-1","source":"amlr","cite":"Article 10(1), first subparagraph","topic":"The firm-wide risk assessment","quote":"Obliged entities shall take appropriate measures, proportionate to the nature of their business, including its risks and complexity, and their size, to identify and assess the risks of money laundering and terrorist financing to which they are exposed, as well as the risks of non-implementation and evasion of targeted financial sanctions, taking into account at least: (a) the risk variables set out in Annex I and the risk factors set out in Annexes II and III; (b) the findings of the risk assessment at Union level conducted by the Commission pursuant to Article 7 of Directive (EU) 2024/1640; (c) the findings of the national risk assessments carried out by the Member States pursuant to Article 8 of Directive (EU) 2024/1640, as well as of any relevant sector-specific risk assessment carried out by the Member States; (d) relevant information published by international standard setters in the AML/CFT area or, at the level of the Union, relevant publications by the Commission or by AMLA; (e) information on money laundering and terrorist financing risks provided by competent authorities; (f) information on the customer base.","excerpt":false,"plain":"Every firm must assess the money laundering risk of its own business, using EU and national risk assessments, supervisor information and its own customer base.","asks":["do we need a business risk assessment","what is a business wide risk assessment","enterprise wide risk assessment","what must the risk assessment consider"],"keywords":["business-wide","enterprise-wide","firm-wide","risk assessment","ewra","risk variables","customer base"]},{"id":"amlr-10-1b","source":"amlr","cite":"Article 10(1), second subparagraph","topic":"Assess risk before launching new products","quote":"Prior to the launch of new products, services or business practices, including the use of new delivery channels and new or developing technologies, in conjunction with new or pre-existing products and services or before starting to provide an existing service or product to a new customer segment or in a new geographical area, obliged entities shall identify and assess, in particular, the related money laundering and terrorist financing risks and take appropriate measures to manage and mitigate those risks.","excerpt":false,"plain":"Before launching a new product, delivery channel or technology, a firm must assess the money laundering risks and act to reduce them.","asks":["do we need a risk assessment before launching a new product","new product risk assessment","new technology aml risk"],"keywords":["new product","launch","new technology","delivery channel","new service","product approval"]},{"id":"amlr-69-1","source":"amlr","cite":"Article 69(1), first subparagraph, point (a)","topic":"Reporting suspicions to the financial intelligence unit","quote":"Obliged entities, and, where applicable, their directors and employees, shall cooperate fully with the FIU by promptly: (a) reporting to the FIU, on their own initiative, where the obliged entity knows, suspects or has reasonable grounds to suspect that funds or activities, regardless of the amount involved, are the proceeds of criminal activity or are related to terrorist financing or criminal activity and by responding to requests by the FIU for additional information in such cases;","excerpt":true,"plain":"A firm must report to the financial intelligence unit when it knows, suspects or has reasonable grounds to suspect that funds are criminal proceeds or linked to terrorist financing, whatever the amount.","asks":["when must we file a suspicious transaction report","when to report to the FIU","do we report below a threshold","what is the duty to report suspicion","SAR STR obligation"],"keywords":["sar","str","suspicious activity report","suspicious transaction report","report","fiu","financial intelligence unit","suspect","reasonable grounds","regardless of the amount","no threshold"]},{"id":"amlr-69-1b","source":"amlr","cite":"Article 69(1), second subparagraph","topic":"Attempted transactions must be reported too","quote":"All suspicious transactions, including attempted transactions and suspicions arising from the inability to conduct customer due diligence shall be reported in accordance with the first subparagraph.","excerpt":false,"plain":"Attempted transactions, and suspicions that arise because customer checks could not be completed, must be reported as well.","asks":["do we report attempted transactions","must failed transactions be reported","report suspicion when customer refuses kyc"],"keywords":["attempted","failed","refused","inability","customer due diligence","report"]},{"id":"amlr-69-2","source":"amlr","cite":"Article 69(2), second subparagraph","topic":"What a suspicion can be based on","quote":"A suspicion pursuant to paragraph 1, point (a), shall be based on the characteristics of the customer and their counterparts, the size and nature of the transaction or activity or the methods and patterns thereof, the link between several transactions or activities, the origin, destination or use of funds, or any other circumstance known to the obliged entity, including the consistency of the transaction or activity with the information obtained pursuant to Chapter III including the risk profile of the client.","excerpt":false,"plain":"A suspicion should rest on facts such as who the customer and counterparties are, the size and pattern of transactions, links between them, and where the money comes from and goes.","asks":["what counts as suspicious","what is a suspicion based on","what indicators of suspicion","how to decide if a transaction is suspicious"],"keywords":["suspicion","suspicious","indicators","patterns","red flags","origin of funds","destination","link between transactions","risk profile"]},{"id":"amlr-71-1","source":"amlr","cite":"Article 71(1)","topic":"Holding a transaction until the report is filed","quote":"Obliged entities shall refrain from carrying out transactions which they know or suspect to be related to proceeds of criminal activity or to terrorist financing until they have submitted a report in accordance with Article 69(1), first subparagraph, point (a), and have complied with any further specific instructions from the FIU or other competent authority in accordance with the applicable law. Obliged entities may carry out the transaction concerned after having assessed the risks of proceeding with the transaction if they have not received instructions to the contrary from the FIU within 3 working days of submitting the report.","excerpt":false,"plain":"A firm must not carry out a transaction it knows or suspects to be criminal until it has reported. After assessing the risks, it may go ahead if the financial intelligence unit has given no instruction to the contrary within 3 working days of the report.","asks":["can we process a transaction we suspect","must we freeze a suspicious payment","how long to wait after reporting","hold transaction pending report"],"keywords":["refrain","hold","freeze","suspend","delay","3 working days","three working days","wait","pending"]},{"id":"amlr-73-1","source":"amlr","cite":"Article 73(1)","topic":"Do not tell the customer (tipping off)","quote":"Obliged entities and their directors, employees, or persons in comparable positions, including agents and distributors, shall not disclose to the customer concerned or to other third persons the fact that transactions or activities are being or have been assessed in accordance with Article 69, that information is being, will be or has been transmitted in accordance with Article 69 or 70 or that a money laundering or terrorist financing analysis is being, or may be, carried out.","excerpt":false,"plain":"A firm and its staff must not tell the customer, or anyone else, that a transaction is being assessed, that a report is being filed, or that an analysis is under way.","asks":["can we tell the customer we reported them","what is tipping off","can we inform the customer about a suspicious activity report","disclosure to customer of suspicion"],"keywords":["tipping off","tip off","disclose","disclosure","inform the customer","confidential","secret"]},{"id":"amlr-77-3","source":"amlr","cite":"Article 77(3), first subparagraph","topic":"How long records must be kept","quote":"The information referred to in paragraphs 1 and 2 shall be retained for a period of 5 years commencing on the date of the termination of the business relationship or on the date of the carrying out of the occasional transaction, or on the date of refusal to enter into a business relationship or carry out an occasional transaction.","excerpt":false,"plain":"Records are kept for 5 years, counted from when the relationship ends, the occasional transaction takes place, or the firm refuses to onboard or transact.","asks":["how long do we keep records","record retention period","data retention aml","how long to keep kyc documents"],"keywords":["retention","retain","keep","records","five years","5 years","delete","storage","documents"]},{"id":"amlr-79-1","source":"amlr","cite":"Article 79(1), first subparagraph","topic":"Anonymous accounts and privacy coins are banned","quote":"Credit institutions, financial institutions and crypto-asset service providers shall be prohibited from keeping anonymous bank and payment accounts, anonymous passbooks, anonymous safe-deposit boxes or anonymous crypto-asset accounts as well as any account otherwise allowing for the anonymisation of the customer account holder or the anonymisation or increased obfuscation of transactions, including through anonymity-enhancing coins.","excerpt":false,"plain":"Banks, financial institutions and crypto-asset service providers may not keep anonymous accounts, or accounts that allow customers or transactions to be hidden, including through anonymity-enhancing coins.","asks":["are privacy coins allowed","can a crypto exchange list monero","anonymous accounts rule","anonymity enhancing coins"],"keywords":["privacy coin","privacy coins","anonymity-enhancing","anonymous","monero","zcash","obfuscation","mixer","crypto"]},{"id":"amlr-80-1","source":"amlr","cite":"Article 80(1)","topic":"Cash payment limit","quote":"Persons trading in goods or providing services may accept or make a payment in cash only up to an amount of EUR 10 000 or the equivalent in national or foreign currency, whether the transaction is carried out in a single operation or in several operations which appear to be linked.","excerpt":false,"plain":"Businesses selling goods or services may accept or make cash payments only up to 10,000 euro, counting payments that appear to be linked together.","asks":["what is the cash limit","maximum cash payment in the EU","10000 euro cash"],"keywords":["cash","limit","10000","10 000","ceiling","cap","linked"]},{"id":"amlr-90","source":"amlr","cite":"Article 90, second paragraph","topic":"When the regulation applies","quote":"It shall apply from 10 July 2027, except in relation to obliged entities referred to in Article 3, points (3)(n) and (o), to which it shall apply from 10 July 2029.","excerpt":false,"plain":"The Anti-Money Laundering Regulation applies from 10 July 2027, with a later date of 10 July 2029 for the entities named in Article 3, points (3)(n) and (o).","asks":["when does the AMLR apply","when does the new anti money laundering regulation start","amlr application date","when does 2024/1624 enter into application"],"keywords":["applies","application date","effective","in force","july 2027","2027","deadline","start date","amlr","timeline"]},{"id":"tfr-14-1","source":"tfr","cite":"Article 14(1)","topic":"Travel rule: information about the sender","quote":"The crypto-asset service provider of the originator shall ensure that transfers of crypto-assets are accompanied by the following information on the originator: (a) the name of the originator; (b) the originator’s distributed ledger address, in cases where a transfer of crypto-assets is registered on a network using DLT or similar technology, and the crypto-asset account number of the originator, where such an account exists and is used to process the transaction; (c) the originator’s crypto-asset account number, in cases where a transfer of crypto-assets is not registered on a network using DLT or similar technology; (d) the originator’s address, including the name of the country, official personal document number and customer identification number, or, alternatively, the originator’s date and place of birth; and (e) subject to the existence of the necessary field in the relevant message format, and where provided by the originator to its crypto-asset service provider, the current LEI or, in its absence, any other available equivalent official identifier of the originator.","excerpt":false,"plain":"The sender's crypto firm must send certain information about the sender with every transfer: name, wallet address or account number, address and identity number or date and place of birth, and a legal entity identifier where available.","asks":["what is the travel rule","what information must accompany a crypto transfer","originator information crypto transfer","what data do we send with a crypto transaction"],"keywords":["travel rule","originator","sender","information accompanying","wallet address","name","date of birth","lei","crypto transfer"]},{"id":"tfr-14-2","source":"tfr","cite":"Article 14(2)","topic":"Travel rule: information about the recipient","quote":"The crypto-asset service provider of the originator shall ensure that transfers of crypto-assets are accompanied by the following information on the beneficiary: (a) the name of the beneficiary; (b) the beneficiary’s distributed ledger address, in cases where a transfer of crypto-assets is registered on a network using DLT or similar technology, and the beneficiary’s crypto-asset account number, where such an account exists and is used to process the transaction; (c) the beneficiary’s crypto-asset account number, in cases where a transfer of crypto-assets is not registered on a network using DLT or similar technology; and (d) subject to the existence of the necessary field in the relevant message format, and where provided by the originator to its crypto-asset service provider, the current LEI or, in its absence, any other available equivalent official identifier of the beneficiary.","excerpt":false,"plain":"The sender's crypto firm must also send the recipient's name, wallet address or account number, and a legal entity identifier where available.","asks":["what beneficiary information is needed for a crypto transfer","beneficiary information travel rule","recipient details crypto transfer"],"keywords":["travel rule","beneficiary","recipient","receiver","information accompanying","wallet address","crypto transfer"]},{"id":"tfr-14-4","source":"tfr","cite":"Article 14(4)","topic":"Travel rule: when the information must be sent","quote":"The information referred to in paragraphs 1 and 2 shall be submitted in advance of, or simultaneously or concurrently with, the transfer of crypto-assets and in a secure manner and in accordance with Regulation (EU) 2016/679. The information referred to in paragraphs 1 and 2 shall not be required to be attached directly to, or be included in, the transfer of crypto-assets.","excerpt":false,"plain":"The information must be sent before or together with the transfer, securely. It does not have to be written into the transfer itself.","asks":["when must travel rule information be sent","does the information have to be in the blockchain transaction","travel rule timing"],"keywords":["travel rule","timing","before","simultaneously","attached","secure","blockchain"]},{"id":"tfr-14-5","source":"tfr","cite":"Article 14(5), second sentence","topic":"Sending more than 1,000 euro to a self-hosted wallet","quote":"Without prejudice to specific risk mitigating measures taken in accordance with Article 19b of Directive (EU) 2015/849, in the case of a transfer of an amount exceeding EUR 1 000 to a self-hosted address, the crypto-asset service provider of the originator shall take adequate measures to assess whether that address is owned or controlled by the originator.","excerpt":false,"plain":"For transfers above 1,000 euro to a self-hosted wallet, the sender's crypto firm must take adequate steps to assess whether the customer owns or controls that wallet.","asks":["do we need to verify ownership of an unhosted wallet","unhosted wallet over 1000 euro","self-hosted wallet ownership check","withdrawal to private wallet"],"keywords":["self-hosted","unhosted","private wallet","1000","ownership","owned or controlled","withdrawal","outgoing","crypto"]},{"id":"tfr-14-6","source":"tfr","cite":"Article 14(6)","topic":"Verify the sender information before transferring","quote":"Before transferring crypto-assets, the crypto-asset service provider of the originator shall verify the accuracy of the information referred to in paragraph 1 on the basis of documents, data or information obtained from a reliable and independent source.","excerpt":false,"plain":"Before sending crypto, the sender's firm must check that the sender information is accurate, using documents, data or information from a reliable and independent source.","asks":["must we verify originator information","verify sender details before crypto transfer","travel rule verification"],"keywords":["travel rule","verify","verification","accuracy","reliable","independent source","originator"]},{"id":"tfr-17-1","source":"tfr","cite":"Article 17(1), points (a) and (b)","topic":"Incoming crypto transfer with missing information","quote":"(a) reject the transfer or return the transferred crypto-assets to the originator’s crypto-asset account; or (b) request the required information on the originator and the beneficiary before making the crypto-assets available to the beneficiary.","excerpt":true,"plain":"If information about the sender or recipient is missing or incomplete, the receiving firm must either reject or return the transfer, or ask for the information before making the crypto available.","asks":["what if travel rule information is missing","incoming transfer without originator information","reject or return a crypto transfer","missing beneficiary information"],"keywords":["travel rule","missing","incomplete","reject","return","incoming","originator","request information"]},{"id":"tfr-18","source":"tfr","cite":"Article 18","topic":"Missing travel rule data is a suspicion factor","quote":"The crypto-asset service provider of the beneficiary shall take into account missing or incomplete information on the originator or the beneficiary as a factor when assessing whether a transfer of crypto-assets, or any related transaction, is suspicious and whether it is to be reported to the FIU in accordance with Directive (EU) 2015/849.","excerpt":false,"plain":"Missing or incomplete sender or recipient information counts as a factor when deciding whether a crypto transfer is suspicious and should be reported.","asks":["is missing travel rule data suspicious","should we report incomplete transfer information","missing information as a red flag"],"keywords":["travel rule","missing","incomplete","red flag","suspicious","report","factor"]},{"id":"tfr-3-20","source":"tfr","cite":"Article 3, point (20)","topic":"What a self-hosted address is","quote":"‘self-hosted address’ means a distributed ledger address not linked to either of the following: (a) a crypto-asset service provider; (b) an entity not established in the Union and providing services similar to those of a crypto-asset service provider;","excerpt":false,"plain":"A self-hosted address is a wallet address that is not linked to a crypto-asset service provider, or to a similar provider outside the EU.","asks":["what is a self-hosted address","define unhosted wallet","what counts as a self hosted wallet"],"keywords":["self-hosted","unhosted","definition","wallet","distributed ledger address","private wallet"]},{"id":"fatf-r1-a","source":"fatf","cite":"Recommendation 1","topic":"The risk-based approach","quote":"Countries should identify, assess, and understand the money laundering and terrorist financing risks for the country, and should take action, including designating an authority or mechanism to coordinate actions to assess risks, and apply resources, aimed at ensuring the risks are mitigated effectively. Based on that assessment, countries should apply a risk-based approach (RBA) to ensure that measures to prevent or mitigate money laundering and terrorist financing are proportionate to the risks identified.","excerpt":false,"plain":"The international standard asks countries to assess their money laundering and terrorist financing risks and to make prevention measures proportionate to those risks.","asks":["what is the risk based approach","what does FATF say about risk assessment","why risk based","FATF recommendation 1"],"keywords":["rba","risk-based approach","risk based","proportionate","risk assessment","fatf","recommendation 1","national risk assessment"]},{"id":"fatf-r1-b","source":"fatf","cite":"Recommendation 1","topic":"Higher risk gets stronger measures, lower risk simpler ones","quote":"Where countries identify higher risks, they should ensure that their AML/CFT regime adequately addresses such risks. Where countries identify lower risks, they should allow and encourage simplified measures as appropriate.","excerpt":false,"plain":"Where risk is higher the regime must address it. Where risk is lower, simplified measures are allowed and encouraged.","asks":["when are simplified measures allowed","what to do with higher risks FATF","lower risk simplified measures"],"keywords":["higher risk","lower risk","simplified","fatf","recommendation 1","proportionate"]},{"id":"fatf-r10-anon","source":"fatf","cite":"Recommendation 10","topic":"No anonymous accounts (FATF)","quote":"Financial institutions should be prohibited from keeping anonymous accounts or accounts in obviously fictitious names.","excerpt":false,"plain":"The international standard says financial institutions should not keep anonymous accounts or accounts in obviously fictitious names.","asks":["are anonymous accounts allowed","fictitious names accounts","FATF anonymous accounts"],"keywords":["anonymous","fictitious","fatf","recommendation 10","accounts"]},{"id":"fatf-r10-ongoing","source":"fatf","cite":"Recommendation 10, measure (d)","topic":"Ongoing due diligence (FATF)","quote":"Conducting ongoing due diligence on the business relationship and scrutiny of transactions undertaken throughout the course of that relationship to ensure that the transactions being conducted are consistent with the institution’s knowledge of the customer, their business and risk profile, including, where necessary, the source of funds.","excerpt":false,"plain":"The international standard asks for ongoing due diligence and scrutiny of transactions to check they are consistent with what the institution knows about the customer, their business and risk profile.","asks":["what does FATF say about ongoing due diligence","FATF transaction monitoring","scrutiny of transactions fatf"],"keywords":["ongoing","scrutiny","transactions","monitoring","fatf","recommendation 10","risk profile","source of funds"]},{"id":"fatf-r10-rba","source":"fatf","cite":"Recommendation 10","topic":"Customer due diligence depth follows risk (FATF)","quote":"Financial institutions should be required to apply each of the CDD measures under (a) to (d) above, but should determine the extent of such measures using a risk-based approach (RBA) in accordance with the Interpretive Notes to this Recommendation and to Recommendation 1.","excerpt":false,"plain":"All the customer due diligence measures apply, but how far each one goes should follow a risk-based approach.","asks":["does FATF allow risk based customer due diligence","FATF kyc extent risk based"],"keywords":["cdd","customer due diligence","extent","risk-based","fatf","recommendation 10"]},{"id":"fatf-r11","source":"fatf","cite":"Recommendation 11","topic":"Record keeping (FATF)","quote":"Financial institutions should be required to maintain, for at least five years, all necessary records on transactions, both domestic and international, to enable them to comply swiftly with information requests from the competent authorities.","excerpt":false,"plain":"The international standard asks financial institutions to keep all necessary transaction records for at least five years.","asks":["how long does FATF say to keep records","FATF record keeping five years"],"keywords":["record","retention","five years","fatf","recommendation 11","transactions"]},{"id":"fatf-r12-a","source":"fatf","cite":"Recommendation 12, foreign politically exposed persons (opening)","topic":"Foreign politically exposed persons (FATF)","quote":"Financial institutions should be required, in relation to foreign politically exposed persons (PEPs) (whether as customer or beneficial owner), in addition to performing normal customer due diligence measures, to: (a) have appropriate risk-management systems to determine whether the customer or the beneficial owner is a politically exposed person; (b) obtain senior management approval for establishing (or continuing, for existing customers) such business relationships;","excerpt":true,"plain":"For foreign politically exposed persons, the standard asks for systems to identify them and senior management approval, among other measures. This excerpt shows the first two. The source lists more.","asks":["what does FATF say about PEPs","foreign pep requirements fatf","FATF recommendation 12"],"keywords":["pep","politically exposed","foreign","fatf","recommendation 12","senior management"]},{"id":"fatf-r12-b","source":"fatf","cite":"Recommendation 12","topic":"Family members and close associates of PEPs (FATF)","quote":"The requirements for all types of PEP should also apply to family members or close associates of such PEPs.","excerpt":false,"plain":"The requirements for politically exposed persons also apply to their family members and close associates.","asks":["are family members of a PEP covered","close associates of politically exposed persons","pep relatives"],"keywords":["family","relatives","close associates","pep","politically exposed","fatf"]},{"id":"fatf-r15-a","source":"fatf","cite":"Recommendation 15, new technologies","topic":"Assess risk of new products and technology (FATF)","quote":"Countries and financial institutions should identify and assess the money laundering or terrorist financing risks that may arise in relation to (a) the development of new products and new business practices, including new delivery mechanisms, and (b) the use of new or developing technologies for both new and pre-existing products.","excerpt":false,"plain":"Countries and financial institutions should assess the risks of new products, new business practices and new technologies.","asks":["does FATF require risk assessment for new products","new technologies fatf","FATF recommendation 15"],"keywords":["new technologies","new products","new delivery mechanisms","fatf","recommendation 15"]},{"id":"fatf-r15-b","source":"fatf","cite":"Recommendation 15, virtual assets","topic":"Virtual asset service providers must be regulated (FATF)","quote":"To manage and mitigate the risks emerging from virtual assets, countries should ensure that virtual asset service providers are regulated for AML/CFT purposes, and licensed or registered and subject to effective systems for monitoring and ensuring compliance with the relevant measures called for in the FATF Recommendations.","excerpt":false,"plain":"Countries should regulate virtual asset service providers for money laundering and terrorist financing purposes, and license or register them.","asks":["does FATF regulate crypto","FATF virtual asset service providers","must crypto exchanges be licensed","vasp regulation"],"keywords":["vasp","virtual asset service provider","crypto exchange","licensed","registered","regulated","fatf","crypto"]},{"id":"fatf-inr15-r10","source":"fatf","cite":"Interpretive Note to Recommendation 15, on Recommendation 10","topic":"Customer due diligence threshold for crypto firms (FATF)","quote":"R. 10 – The occasional transactions designated threshold above which VASPs are required to conduct CDD is USD/EUR 1 000.","excerpt":false,"plain":"The international standard sets the threshold for occasional transactions at USD or EUR 1,000 for virtual asset service providers.","asks":["what is the FATF threshold for VASPs","crypto kyc threshold fatf","1000 usd eur"],"keywords":["vasp","threshold","1000","occasional","cdd","fatf","crypto"]},{"id":"fatf-r16","source":"fatf","cite":"Recommendation 16","topic":"Payment transparency, the basis of the travel rule (FATF)","quote":"Countries should ensure that financial institutions include required and accurate originator information, and required beneficiary information, on payments or value transfers and related messages.","excerpt":false,"plain":"Financial institutions should include required and accurate sender information, and required recipient information, on payments and value transfers.","asks":["what does FATF say about the travel rule","FATF recommendation 16","wire transfer information requirements"],"keywords":["travel rule","wire transfer","payment transparency","originator","beneficiary","fatf","recommendation 16"]},{"id":"fatf-r19","source":"fatf","cite":"Recommendation 19","topic":"Higher-risk countries (FATF)","quote":"Financial institutions should be required to apply enhanced due diligence measures to business relationships and transactions with natural and legal persons, and financial institutions, from countries for which this is called for by the FATF.","excerpt":false,"plain":"Where the FATF calls for it, financial institutions should apply enhanced due diligence to customers and transactions connected with a listed country.","asks":["what to do with customers from high risk countries","FATF high risk jurisdictions","call for action countries","grey list black list customers"],"keywords":["high-risk countries","higher-risk countries","high risk jurisdiction","grey list","black list","call for action","enhanced due diligence","fatf","country risk"]},{"id":"fatf-r20","source":"fatf","cite":"Recommendation 20","topic":"Reporting suspicious transactions (FATF)","quote":"If a financial institution suspects or has reasonable grounds to suspect that funds are the proceeds of a criminal activity, or are related to terrorist financing, it should be required, by law, to report promptly its suspicions to the financial intelligence unit (FIU).","excerpt":false,"plain":"The international standard says that a firm which suspects, or has reasonable grounds to suspect, that funds are criminal proceeds or linked to terrorist financing must report promptly to the financial intelligence unit.","asks":["what does FATF say about suspicious transaction reports","FATF recommendation 20","when to report suspicion fatf"],"keywords":["str","sar","suspicious","report","fiu","fatf","recommendation 20","promptly"]},{"id":"fatf-glossary-va","source":"fatf","cite":"Glossary, definition of virtual asset","topic":"What a virtual asset is (FATF)","quote":"A virtual asset is a digital representation of value that can be digitally traded, or transferred, and can be used for payment or investment purposes.","excerpt":false,"plain":"The FATF defines a virtual asset as a digital representation of value that can be traded or transferred and used for payment or investment.","asks":["what is a virtual asset","FATF definition of virtual asset","definition of crypto asset fatf"],"keywords":["virtual asset","definition","crypto","digital representation of value","fatf","glossary"]}]};
